-- AD35 CHECK (B13 T4h signed ledger checkpoints + T4i company identifiers and proven register shapes): every row must be true
SELECT 'the six ckpt.* / ident.* ledger kinds exist, both refused kinds are high' AS rule, (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('ckpt.recorded', 'ckpt.refused', 'ident.recorded', 'ident.superseded', 'ident.ended', 'ident.refused')) = 6 AND (SELECT count(*) FROM desk.fadm_ledger_kind WHERE kind IN ('ckpt.refused', 'ident.refused') AND severity = 'high') = 2 AS ok
UNION ALL SELECT 'desk_proof_owner is NOLOGIN, no superuser, no BYPASSRLS', EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'desk_proof_owner' AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
UNION ALL SELECT 'the four new tables are forced RLS, closed to PUBLIC and to desk_app, with a deny-all policy',
  (SELECT bool_and(c.relrowsecurity AND c.relforcerowsecurity) FROM pg_class c WHERE c.oid IN ('desk.ledger_checkpoint'::regclass, 'desk.ledger_checkpoint_witness'::regclass, 'desk.company_identifier'::regclass, 'desk.ledger_merkle_root'::regclass))
  AND NOT has_table_privilege('public', 'desk.ledger_checkpoint', 'SELECT') AND NOT has_table_privilege('desk_app', 'desk.ledger_checkpoint', 'SELECT') AND NOT has_table_privilege('desk_app', 'desk.ledger_checkpoint_witness', 'INSERT') AND NOT has_table_privilege('desk_app', 'desk.company_identifier', 'SELECT') AND NOT has_table_privilege('desk_app', 'desk.company_identifier', 'UPDATE')
  AND (SELECT count(*) FROM pg_policies WHERE schemaname = 'desk' AND policyname IN ('p_ckpt_none', 'p_ckpt_witness_none', 'p_ident_none')) = 3
UNION ALL SELECT 'checkpoint and witness tables are append-only: update, delete and truncate triggers exist', (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('ledger_checkpoint_frozen', 'ledger_checkpoint_frozen_t', 'ledger_checkpoint_witness_frozen', 'ledger_checkpoint_witness_frozen_t', 'ledger_checkpoint_guard')) = 5
UNION ALL SELECT 'a checkpoint row is bound by table rules: origin constant, 32-byte root, 64-byte signature, 16-hex key id, one row per (origin, size, key)',
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.ledger_checkpoint'::regclass AND conname = 'ledger_checkpoint_one_per_key')
  AND (SELECT count(*) FROM pg_constraint WHERE conrelid = 'desk.ledger_checkpoint'::regclass AND contype = 'c') >= 6
UNION ALL SELECT 'the C2SP body is derived by one immutable function: origin, size, base64 root, each line ending in LF', desk.ledger_checkpoint_body(7, decode(repeat('00', 32), 'hex')) = desk.ledger_origin() || E'\n7\n' || encode(decode(repeat('00', 32), 'hex'), 'base64') || E'\n' AND (SELECT provolatile FROM pg_proc WHERE oid = 'desk.ledger_checkpoint_body(bigint,bytea)'::regprocedure) = 'i'
UNION ALL SELECT 'every stored checkpoint matches the ledger line it names and the ledger between checkpoints recomputes (FACT)', NOT EXISTS (SELECT 1 FROM desk.ledger_checkpoint_verify(200) WHERE outcome NOT IN ('ok', 'range_too_large'))
UNION ALL SELECT 'company_identifier: two-people CHECK, period CHECK, end-pair CHECK, two live-only unique indexes (one holder per number, one number per company per register)',
  EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.company_identifier'::regclass AND conname = 'company_identifier_two_people')
  AND EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.company_identifier'::regclass AND conname = 'company_identifier_period')
  AND EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'desk.company_identifier'::regclass AND conname = 'company_identifier_end_pair')
  AND (SELECT count(*) FROM pg_indexes WHERE schemaname = 'desk' AND indexname IN ('company_identifier_live_number', 'company_identifier_live_tenant') AND indexdef ILIKE '%UNIQUE%' AND indexdef ILIKE '%valid_to IS NULL%') = 2
UNION ALL SELECT 'company_identifier guard trigger blocks delete, truncate and every update except closing a live row', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'desk.company_identifier'::regclass AND tgname IN ('company_identifier_guard', 'company_identifier_guard_t') AND NOT tgisinternal) = 2
UNION ALL SELECT 'the identifier ledger never holds a company number and only closed keys (FACT)', NOT EXISTS (SELECT 1 FROM desk.fadm_ledger l, jsonb_object_keys(l.detail) k WHERE l.kind LIKE 'ident.%' AND k NOT IN ('identifier_id', 'registry_id', 'shape_state', 'number_hash', 'reason', 'why'))
  AND NOT EXISTS (SELECT 1 FROM desk.fadm_ledger l WHERE l.kind LIKE 'ckpt.%' AND EXISTS (SELECT 1 FROM jsonb_object_keys(l.detail) k WHERE k NOT IN ('tree_size', 'key_id', 'why')))
UNION ALL SELECT 'every live and past identifier has two different people (FACT over all rows)', NOT EXISTS (SELECT 1 FROM desk.company_identifier WHERE recorded_by = confirmed_by)
UNION ALL SELECT 'no company holds two live numbers in one register and no number has two live holders (FACT)', NOT EXISTS (SELECT 1 FROM desk.company_identifier WHERE valid_to IS NULL GROUP BY tenant_id, registry_id HAVING count(*) > 1) AND NOT EXISTS (SELECT 1 FROM desk.company_identifier WHERE valid_to IS NULL GROUP BY registry_id, number_norm HAVING count(*) > 1)
UNION ALL SELECT 'the AD35 doors are owned by desk_proof_owner, SECURITY DEFINER, search_path pinned, commented, closed to PUBLIC',
  (SELECT count(*) FROM pg_proc p JOIN pg_roles r ON r.oid = p.proowner WHERE p.pronamespace = 'desk'::regnamespace AND r.rolname = 'desk_proof_owner' AND p.prosecdef AND p.proconfig::text LIKE '%search_path=pg_catalog, desk%' AND p.proconfig::text NOT LIKE '%public%'
    AND p.proname IN ('ledger_checkpoint_head', 'ledger_checkpoint_put', 'ledger_checkpoint_witnessed', 'ledger_checkpoint_verify', 'ledger_checkpoint_status', 'ledger_range_ok', 'company_identifier_set', 'company_identifier_end', 'company_identifier_lookup', 'company_identifier_history', 'registry_shape_prove', 'registry_countries', 'registry_pick', 'merkle_leaves', 'ledger_merkle_head', 'ledger_merkle_record', 'ledger_merkle_inclusion', 'ledger_merkle_consistency', 'company_identifier_as_of', 'company_identifier_review_due', 'company_identifier_conflicts', 'company_identifier_stats', 'ad35_selfcheck')) = 23
  AND NOT has_function_privilege('public', 'desk.ledger_checkpoint_put(bigint,text,bytea)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.company_identifier_set(uuid,uuid,uuid,bigint,text)', 'EXECUTE')
UNION ALL SELECT 'the app role may run the doors it needs and can NOT run registry_shape_prove (migration only) or the internal helpers',
  has_function_privilege('desk_app', 'desk.ledger_checkpoint_put(bigint,text,bytea)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.ledger_checkpoint_head()', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.company_identifier_set(uuid,uuid,uuid,bigint,text)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.registry_pick(text)', 'EXECUTE')
  AND NOT has_function_privilege('desk_app', 'desk.registry_shape_prove(bigint,text,text,date,text[],text[])', 'EXECUTE') AND NOT has_function_privilege('desk_app', 'desk.ledger_range_ok(bigint,bigint)', 'EXECUTE') AND NOT has_function_privilege('desk_app', 'desk.company_identifier_refuse(uuid,text)', 'EXECUTE')
UNION ALL SELECT 'registry_kind identity columns are frozen by a trigger; a shape can only enter through the proof function (source + date + samples)',
  EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid = 'desk.registry_kind'::regclass AND tgname = 'registry_kind_cols_frozen' AND NOT tgisinternal) AND (SELECT prosrc ILIKE '%samples_disagree%' AND prosrc ILIKE '%runaway_shape%' AND prosrc ILIKE '%bad_source%' FROM pg_proc WHERE oid = 'desk.registry_shape_prove(bigint,text,text,date,text[],text[])'::regprocedure)
UNION ALL SELECT 'every proven shape (FACT) is anchored, has an https source and a check date', NOT EXISTS (SELECT 1 FROM desk.registry_kind WHERE number_shape IS NOT NULL AND (left(number_shape, 1) <> '^' OR right(number_shape, 1) <> '$' OR shape_source !~ '^https://' OR shape_checked_on IS NULL))
UNION ALL SELECT 'registry_normalise is immutable and strips spaces, dashes and control characters', desk.registry_normalise(' ab-12 3 ') = 'AB123' AND (SELECT provolatile FROM pg_proc WHERE oid = 'desk.registry_normalise(text)'::regprocedure) = 'i'
UNION ALL SELECT 'the pickers list every jurisdiction and the registers of Pakistan', jsonb_array_length(desk.registry_countries()) >= 234 AND desk.registry_pick('PK')::text LIKE '%RA000475%' AND desk.registry_pick('PK')::text LIKE '%RA001111%' AND desk.registry_pick('pk') = '[]'::jsonb
UNION ALL SELECT 'the status door answers a closed state word', desk.ledger_checkpoint_status()->>'state' IN ('none', 'fresh', 'stale', 'broken')
UNION ALL SELECT 'the head door answers the C2SP body of the newest ledger line', (SELECT desk.ledger_checkpoint_head()->>'body' = desk.ledger_checkpoint_body(l.seq, l.hash) FROM desk.fadm_ledger l ORDER BY seq DESC LIMIT 1)
UNION ALL SELECT 'the ledger chain still verifies', desk.fadm_ledger_verify()
UNION ALL SELECT 'RFC 9162 reference hashes: empty tree and empty leaf match the published values, the pure functions are immutable', desk.merkle_mth(ARRAY[]::bytea[], 0, 0) = decode('e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855', 'hex') AND desk.merkle_leaf(''::bytea) = decode('6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d', 'hex')
  AND (SELECT bool_and(provolatile = 'i') FROM pg_proc WHERE oid IN ('desk.merkle_leaf(bytea)'::regprocedure, 'desk.merkle_node(bytea,bytea)'::regprocedure, 'desk.merkle_mth(bytea[],integer,integer)'::regprocedure, 'desk.merkle_verify_inclusion(bytea,bigint,bigint,bytea[],bytea)'::regprocedure, 'desk.merkle_verify_consistency(bigint,bigint,bytea,bytea,bytea[])'::regprocedure))
UNION ALL SELECT 'stored Merkle roots are append-only (update, delete, truncate triggers) and recompute from the ledger (FACT, newest 3)', (SELECT count(*) FROM pg_trigger WHERE tgrelid = 'desk.ledger_merkle_root'::regclass AND tgname IN ('ledger_merkle_root_frozen', 'ledger_merkle_root_frozen_t') AND NOT tgisinternal) = 2
  AND NOT EXISTS (SELECT 1 FROM (SELECT tree_size, root_hash FROM desk.ledger_merkle_root ORDER BY tree_size DESC LIMIT 3) r WHERE desk.merkle_leaves(r.tree_size) IS NULL OR desk.merkle_mth(desk.merkle_leaves(r.tree_size), 0, r.tree_size::integer) <> r.root_hash)
UNION ALL SELECT 'a monitor can verify with the pure functions only: desk_app may run the verifiers and the proof doors, not the internal leaf loader', has_function_privilege('desk_app', 'desk.merkle_verify_inclusion(bytea,bigint,bigint,bytea[],bytea)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.ledger_merkle_inclusion(bigint,bigint)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.ledger_merkle_consistency(bigint,bigint)', 'EXECUTE') AND NOT has_function_privilege('desk_app', 'desk.merkle_leaves(bigint)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.ledger_merkle_record(bigint)', 'EXECUTE')
UNION ALL SELECT 'the as-of, review, conflicts and statistics readers exist for staff and are closed to PUBLIC', has_function_privilege('desk_app', 'desk.company_identifier_as_of(uuid,uuid,timestamptz,timestamptz)', 'EXECUTE') AND has_function_privilege('desk_app', 'desk.company_identifier_stats(uuid)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.company_identifier_review_due(uuid,integer)', 'EXECUTE') AND NOT has_function_privilege('public', 'desk.company_identifier_conflicts(uuid)', 'EXECUTE')
UNION ALL SELECT 'the self-audit answers its nine rules and every one is true', (SELECT count(*) FROM desk.ad35_selfcheck()) = 9 AND (SELECT bool_and(ok) FROM desk.ad35_selfcheck());
